package dev.algorithmlearning.api.reviews.api; import dev.algorithmlearning.api.app.security.CurrentUser; import dev.algorithmlearning.api.reviews.application.*; import jakarta.validation.*; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/reviews") public class ReviewsController {private final ReviewService reviews;private final CurrentUser user;public ReviewsController(ReviewService r,CurrentUser u){reviews=r;user=u;}@PostMapping ResponseEntity<View> create(@Valid @RequestBody Write w){return reviews.create(user.id(),w.problemId(),w.confidence(),w.notes()).map(x->ResponseEntity.status(201).body(View.from(x))).orElseGet(()->ResponseEntity.notFound().build());}@GetMapping("/today") List<View> due(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){return reviews.due(user.id(),page,pageSize).stream().map(View::from).toList();}@GetMapping("/history") List<View> history(@RequestParam(required=false) UUID problemId,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize){return problemId==null?List.of():reviews.history(user.id(),problemId,page,pageSize).stream().map(View::from).toList();}record Write(@NotNull UUID problemId,@Min(0)@Max(4)int confidence,@Size(max=10000)String notes){}record View(UUID id,UUID problemId,int confidence,java.time.Instant reviewedAt,java.time.Instant nextReviewAt,String notes,String policyVersion){static View from(Review r){return new View(r.id(),r.problemId(),r.confidence(),r.reviewedAt(),r.nextReviewAt(),r.notes(),r.policyVersion());}}}
